  { id: "owl", rows: ["#........#", "##########", "#oo####oo#", "#oo#aa#oo#", ".########."] },
  { id: "ghosty", rows: ["..######..", ".########.", ".#o####o#.", ".#o####o#.", "#.##.##.#."] },
