  { id: "claws", rows: ["a........a", "aa.####.aa", ".#o####o#.", "##o####o##", ".########."] },
  { id: "ninja", rows: ["..######..", "aaaaaaaaaa", "a#o####o#a", ".#o####o#.", ".########."] },
