  { id: "wizard", rows: ["....aa....", "...aaaa...", ".aaaaaaaa.", ".#o####o#.", ".#o####o#."] },
  { id: "bandit", rows: [".########.", "##########", "aaoaaaaoaa", "##o####o##", ".########."] },
  { id: "unicorn", rows: ["....aa....", "..######..", ".###oo###.", ".###oo###.", "..######.."] },
