//
// Pure module shared by the herdr plugin and the mod.

const cyc = (t, list, period = 1) => list[Math.floor(t / period) % list.length];
const mid = (text) => ["", text, ""];
const BLANK = ["", "", ""];

function rising(glyphs, frame, period = 3) {
  const step = Math.floor(frame / period) % (glyphs.length + 1);
  const rows = ["", "", ""];
